package com.portfolio.service;
import com.portfolio.dto.CategoryRequest; import com.portfolio.entity.Category; import com.portfolio.repository.CategoryRepository; import org.springframework.stereotype.Service; import java.util.*;
@Service public class CategoryService {private final CategoryRepository repo; public CategoryService(CategoryRepository r){repo=r;} public List<Category> all(){return repo.findAll();} public Category get(Long id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("Category not found"));} public Category create(CategoryRequest r){if(r.name()==null||r.name().isBlank())throw new IllegalArgumentException("Category name is required"); Category c=new Category();c.setName(r.name());c.setDescription(r.description());return repo.save(c);} public Category update(Long id,CategoryRequest r){Category c=get(id);if(r.name()!=null)c.setName(r.name());c.setDescription(r.description());return repo.save(c);} public void delete(Long id){repo.delete(get(id));}}
